// To understand `auto`, consider a template function:
template<typename T>
void func_for_auto(T param);

// Case 3: By-value deduction (strips refs, const, and decays)
const char name[] = "R. N. Briggs"; // type is const char[13]
auto arr1 = name;                  // func_for_auto(name); T is const char*

// Case 1: Reference deduction (preserves type info)
auto& arr2 = name;                 // func_for_auto(name); T is const char(&)[13]

int x = 27;
const int& rx = x;
auto x2 = rx;                      // func_for_auto(rx); T is int
const auto& rx2 = x;               // func_for_auto(x); T is int

// Case 2: Universal reference deduction
auto&& uref1 = x;                  // x is lvalue, so T is int&, uref1 is int&
auto&& uref2 = 27;                 // 27 is rvalue, so T is int, uref2 is int&&
